async function openMedia(){try{const r=await fetch('/api/designer/media'),d=await r.json();if(!r.ok)throw Error(d.error);$('studio-media-list').replaceChildren();const files=d.files.filter(f=>/^(image|video)\//.test(f.content_type));$('studio-media-status').textContent=files.length?files.length+' images and videos available.':'Upload your first collection photograph or video.';for(const file of files){const button=document.createElement('button');button.textContent='Preview · '+file.name;button.onclick=async()=>{try{scene?.pause?.();const media=document.createElement(file.content_type.startsWith('image/')?'img':'video');if(media.tagName==='VIDEO'){media.muted=true;media.playsInline=true;media.loop=true;}await new Promise((resolve,reject)=>{media.onload=resolve;media.onloadeddata=resolve;media.onerror=()=>reject(Error('This media format cannot be displayed by your browser.'));media.src=file.url;});scene=media;videos.set(-1,media);nextCamera=-1;if($('studio-layout').value!=='presentation')$('studio-layout').value='single';select();$('studio-media-status').textContent=file.name+' ready in Preview. Press Take to show it on Programme.';}catch(e){$('studio-media-status').textContent=e.message;}};$('studio-media-list').append(button);if(file.content_type.startsWith('image/')){const edit=document.createElement('button');edit.textContent='Edit · '+file.name;edit.onclick=()=>document.dispatchEvent(new CustomEvent('media-edit-image',{detail:{...file,studioJobId:window.currentStudioJob?.()}}));$('studio-media-list').append(edit);}else if(file.content_type.startsWith('video/')){const edit=document.createElement('button');edit.textContent='Clip · '+file.name;edit.onclick=()=>document.dispatchEvent(new CustomEvent('media-edit-video',{detail:{...file,studioJobId:window.currentStudioJob?.()}}));$('studio-media-list').append(edit);} $('studio-media-list').append(document.createElement('br'));}}catch(e){$('studio-media-status').textContent=e.message;}}
